function Capsule(){return <span className="steel-logo" aria-hidden="true"><RedMark/></span>}
function Avatar({name,color='sand',small=false,big=false,kind}:{name:string;color?:string;small?:boolean;big?:boolean;kind?:string}){return <span className={`avatar ${color} ${small?'small':''} ${big?'big':''}`}>{kind==='saved'?<Bookmark/>:name}</span>}
function useBlob(id?:string){const [url,setUrl]=useState('');useEffect(()=>{let active=true,objectUrl='';setUrl('');if(id)read<Blob>('blobs',id).then(blob=>{if(active&&blob){objectUrl=URL.createObjectURL(blob);setUrl(objectUrl)}}).catch(()=>toast.error('Не удалось открыть вложение'));return()=>{active=false;if(objectUrl)URL.revokeObjectURL(objectUrl)}},[id]);return url}
function Media({message}:{message:Message}){const url=useBlob(message.blobId);if(!message.blobId)return null;if(!url)return <small>Открываем вложение…</small>;if(message.kind==='audio')return <VoicePlayer src={url} duration={message.voice?.duration} waveform={message.voice?.waveform} name={message.fileName||'voice'}/>;if(message.kind==='video')return <video className="round-video" controls playsInline src={url} preload="metadata"/>;return <>{message.mime?.startsWith('image/')&&<img src={url} className="media-img" alt={message.fileName||'Вложение'}/>}<a className="file-link" href={url} download={message.fileName}><FileText/><span>{message.fileName}</span><Download size={15}/></a></>}
function StoryCard({story,onClick}:{story:Story;onClick:()=>void}){const url=useBlob(story.blobId);return <button className={`story-card ${story.color}`} onClick={onClick}>{url&&<img alt="" src={url}/>}<span className="story-author"><Avatar name={initials(story.name)} color={story.color}/>{story.name}</span><span className="story-words">{story.text}</span><small>{story.demo?'Пример истории':'Только на этом устройстве'}</small></button>}
function StoryViewer({story}:{story:Story}){const url=useBlob(story.blobId);return <div className={`story-full ${story.color}`}>{url&&<img alt="История" src={url}/>}<p>{story.text}</p><small>{story.demo?'Демонстрационная история':'Исчезнет из ленты через 24 часа'}</small></div>}
function Recorder({kind,onSave,onCancel}:{kind:'video';onSave:(blob:Blob)=>Promise<void>;onCancel:()=>void}){
 const [status,setStatus]=useState<'idle'|'requesting'|'recording'|'preview'|'saving'>('idle');const [seconds,setSeconds]=useState(0);const [blob,setBlob]=useState<Blob>();const [url,setUrl]=useState('');const rec=useRef<MediaRecorder|null>(null);const stream=useRef<MediaStream|null>(null);const live=useRef<HTMLVideoElement>(null);const mounted=useRef(true);
 useEffect(()=>{mounted.current=true;return()=>{mounted.current=false;if(rec.current?.state==='recording')rec.current.stop();stream.current?.getTracks().forEach(t=>t.stop())}},[]);
 useEffect(()=>{if(!blob)return;const u=URL.createObjectURL(blob);setUrl(u);return()=>URL.revokeObjectURL(u)},[blob]);
 useEffect(()=>{if(status!=='recording')return;const t=setInterval(()=>setSeconds(s=>s+1),1000);return()=>clearInterval(t)},[status]);
 useEffect(()=>{if(seconds>=60&&status==='recording')rec.current?.stop()},[seconds,status]);
 async function start(){try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('Запись недоступна в этом браузере. Можно прикрепить готовый файл.');setStatus('requesting');const s=await navigator.mediaDevices.getUserMedia({audio:true,video:kind==='video'?{facingMode:'user',width:{ideal:480},height:{ideal:480}}:false});if(!mounted.current){s.getTracks().forEach(t=>t.stop());return}stream.current=s;if(live.current){live.current.srcObject=s;void live.current.play().catch(()=>{})}const recorder=new MediaRecorder(s);rec.current=recorder;const chunks:Blob[]=[];let bytes=0;recorder.ondataavailable=e=>{if(e.data.size){chunks.push(e.data);bytes+=e.data.size;if(bytes>24*1024*1024&&recorder.state==='recording')recorder.stop()}};recorder.onerror=()=>{s.getTracks().forEach(t=>t.stop());toast.error('Запись прервана браузером');if(mounted.current)setStatus('idle')};recorder.onstop=()=>{s.getTracks().forEach(t=>t.stop());if(mounted.current){setBlob(new Blob(chunks,{type:recorder.mimeType}));setStatus('preview')}};recorder.start(500);setSeconds(0);setStatus('recording')}catch(e){stream.current?.getTracks().forEach(t=>t.stop());setStatus('idle');toast.error(e instanceof Error?e.message:'Нет доступа к микрофону или камере')}}
 return <><DialogTitle>Видеокружок</DialogTitle><DialogDescription>До 60 секунд. Запись сохраняется только на этом устройстве.</DialogDescription>{kind==='video'&&(status==='preview'||status==='saving'?<video className="record-preview" src={url} controls playsInline/>:<video ref={live} className="record-preview" muted playsInline/>)}<div className="timer">{status==='recording'&&<i className="record-dot"/>}00:{String(seconds).padStart(2,'0')}</div><div className="record-controls">{status==='idle'&&<button className="primary-btn" onClick={start}><Video/>Начать запись</button>}{status==='requesting'&&<p>Разрешите доступ к {kind==='video'?'камере и микрофону':'микрофону'}…</p>}{status==='recording'&&<button className="primary-btn" onClick={()=>rec.current?.stop()}><StopCircle/>Остановить</button>}{(status==='preview'||status==='saving')&&<><button className="secondary-btn" disabled={status==='saving'} onClick={()=>{setBlob(undefined);setUrl('');setSeconds(0);setStatus('idle')}}>Перезаписать</button><button className="primary-btn" disabled={status==='saving'||!blob?.size} onClick={async()=>{if(blob){setStatus('saving');try{await onSave(blob)}catch{setStatus('preview')}}}}>{status==='saving'?'Сохраняем…':'Сохранить в чат'}</button></>}</div><button className="secondary-btn" onClick={onCancel}>Отмена</button></>
}
