 const [creationOpen,setCreationOpen]=useState(false),[publicationOpen,setPublicationOpen]=useState(false),[noteSignal,setNoteSignal]=useState(0);
 const studioRef=useRef<StoryStudioHandle>(null);
 const [marketCreateSignal,setMarketCreateSignal]=useState(0),[marketRefreshSignal,setMarketRefreshSignal]=useState(0);
 const [marketListingId,setMarketListingId]=useState<string>();const listingLinkHandled=useRef(false);


 function openStoryCamera(){setStoryRepost(undefined);setModal('story-new')}
 function chooseCreation(action:CreationAction){setCreationOpen(false);if(action==='sell'){setData(d=>({...d,homeTab:'commissionka'}));setView('feed');setMarketCreateSignal(v=>v+1);return}if(action==='post'){setPublicationOpen(true);return}if(action==='story'){openStoryCamera();return}if(action==='note'){navigate('saved');setNoteSignal(v=>v+1);return}setNewKind(action==='channel'?'channel':'group');setModal('new')}
 const [storyRepost,setStoryRepost]=useState<FeedPost>();
 const [editingMessage,setEditingMessage]=useState<string|null>(null);const [replyTo,setReplyTo]=useState('');const [editSpaceName,setEditSpaceName]=useState('');const [editSpaceBio,setEditSpaceBio]=useState('');const [storyFilter,setStoryFilter]=useState('all');const [storageUsage,setStorageUsage]=useState<number|null>(null);const [profileTarget,setProfileTarget]=useState('me');const [bio,setBio]=useState('');const [handle,setHandle]=useState('');const [localData,setData]=useState<State>(()=>seed(0));const data=useMemo<State>(()=>({...localData,profile:(network.state.session as {displayName?:string})?.displayName||network.state.session?.userId.split(':')[0].slice(1)||localData.profile,spaces:[...localData.spaces,...network.state.rooms.map(room=>({id:room.id,name:room.name,kind:room.kind,initials:initials(room.name),color:'blue',description:'Matrix · E2EE',unread:room.unread}))],messages:[...localData.messages,...network.state.rooms.flatMap(room=>(network.engine?.messages(room.id)||[]).map(message=>({id:message.id,spaceId:room.id,text:message.body,sender:message.sender,own:message.own,createdAt:message.time,kind:'text' as const})))]}),[localData,network.state,network.engine]);const [ready,setReady]=useState(false);const [storageError,setStorageError]=useState(false);const [saving,setSaving]=useState(false);const [view,setView]=useState<View>('feed');const [selected,setSelected]=useState('circle');const [tab,setTab]=useState('all');const [search,setSearch]=useState('');const [mobileChat,setMobileChat]=useState(false);const [modal,setModal]=useState<Modal>(null);const [story,setStory]=useState<Story|null>(null);const [newName,setNewName]=useState('');const [groupUsers,setGroupUsers]=useState('');const [newKind,setNewKind]=useState<'chat'|'group'|'channel'>('chat');const [storyText,setStoryText]=useState('');const [storyFile,setStoryFile]=useState<File>();const [fingerprint,setFingerprint]=useState('');const [keyChecked,setKeyChecked]=useState(false);const [keyBusy,setKeyBusy]=useState(false);const [messageSearch,setMessageSearch]=useState('');const [showMessageSearch,setShowMessageSearch]=useState(false);const [profile,setProfile]=useState('');const [voiceDirty,setVoiceDirty]=useState(false);const [busy,setBusy]=useState(false);const [clock,setClock]=useState(0);const bottom=useRef<HTMLDivElement>(null);const file=useRef<HTMLInputElement>(null);const writeQueue=useRef(Promise.resolve());const saveSequence=useRef(0);const mainRef=useRef(localData);mainRef.current=localData;
 const homeTab=data.homeTab||'all';
 useEffect(()=>{if(!ready||listingLinkHandled.current)return;listingLinkHandled.current=true;const id=new URL(window.location.href).searchParams.get('listing');if(id&&/^[a-f0-9-]{36}$/i.test(id)){setData(d=>({...d,homeTab:'commissionka'}));setView('feed');setMarketListingId(id)}},[ready]);
 useStoriesTray(inboxRef,(view==='chats'||view==='channels')&&!mobileChat,data.reduceMotion);
 useEffect(()=>{document.documentElement.dataset.reduceMotion=String(!!data.reduceMotion);return()=>{delete document.documentElement.dataset.reduceMotion}},[data.reduceMotion]);
 useEffect(()=>{let active=true;setClock(Date.now());loadState().then(s=>{if(active){setData(s);setProfile(s.profile);setBio(s.bio||'');setHandle(s.handle||'');setReady(true)}}).catch(()=>{setStorageError(true);toast.error('Хранилище недоступно. Проверьте настройки браузера.')});identity().then(k=>{if(active)setFingerprint(k.fingerprint)}).catch(()=>{});const timer=setInterval(()=>setClock(Date.now()),60000);return()=>{active=false;clearInterval(timer)}},[]);
 useEffect(()=>{if(!ready)return;const n=++saveSequence.current;setSaving(true);writeQueue.current=writeQueue.current.catch(()=>{}).then(()=>{assertOwner();return saveState(localData)}).then(()=>{if(n===saveSequence.current){setSaving(false);setStorageError(false)}}).catch(()=>{if(n===saveSequence.current){setSaving(false);setStorageError(true)}toast.error('Не удалось сохранить изменения. Возможно, память заполнена.')})},[localData,ready]);
 useEffect(()=>{bottom.current?.scrollIntoView({behavior:'instant'})},[selected,data.messages.length,view]);
 useEffect(()=>{const cb=(e:KeyboardEvent)=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();document.querySelector<HTMLInputElement>('#global-search')?.focus()}};window.addEventListener('keydown',cb);return()=>window.removeEventListener('keydown',cb)},[]);
 useEffect(()=>{const context=(document as Document&{modelContext?:{registerTool:(tool:unknown,options:unknown)=>Promise<void>}}).modelContext;if(!context?.registerTool)return;const controller=new AbortController();try{Promise.resolve(context.registerTool({name:'navigate_presidium',title:'Открыть раздел Presidium',description:'Открывает раздел локальной альфы. Не отправляет сообщения и не читает личную переписку.',inputSchema:{type:'object',properties:{section:{type:'string',enum:['chats','channels','stories','feed','saved','settings']}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:(input:unknown)=>{const section=(input as {section?:View})?.section;if(!section||!['chats','channels','stories','feed','saved','settings'].includes(section))throw Error('Неизвестный раздел');navigate(section);return {section,status:'opened'}}},{signal:controller.signal})).catch(()=>{})}catch{}return()=>controller.abort()},[]);
 useEffect(()=>{if(ready)void loadState().then(state=>setData(state)).catch(()=>toast.error('Не удалось открыть данные аккаунта.'))},[network.state.session?.userId,ready]);
 useEffect(()=>{if(network.activeRoom){setView('chats');setSelected(network.activeRoom);setMobileChat(true)}},[network.activeRoom]);
 const displayTime=(time:number)=>ready?formatTime(time):'—';
 const currentLocalSpace=useRef(selected);currentLocalSpace.current=selected;
 const space=data.spaces.find(s=>s.id===selected)??data.spaces[0];const isChannel=space.kind==='channel';const messages=data.messages.filter(m=>m.spaceId===selected&&(!messageSearch||m.text.toLowerCase().includes(messageSearch.toLowerCase())||m.fileName?.toLowerCase().includes(messageSearch.toLowerCase())));const activeStories=activeStoryItems(data,clock);const draft=data.drafts[selected]??'';
 function navigate(next:View){if(next==='profile-hub'){openProfile('me');return}setComposeSignal(0);if(next==='feed')setFeedQuery('');if(next==='channels'){setView('chats');setTab('channels');setMobileChat(false);setSearch('');return}if(next==='stories'){openStoryCamera();return}setView(next);setTab('all');setMobileChat(false);setSearch('');setMessageSearch('');setShowMessageSearch(false);if(next==='saved')setSelected('saved');if(next==='chats')setSelected('circle')}

 const commitState:CommitState=async update=>{const task=writeQueue.current.catch(()=>{}).then(async()=>{assertOwner();const next=update(mainRef.current);await saveState(next);mainRef.current=next;setData(next);setStorageError(false);});writeQueue.current=task;try{await task}catch(e){setStorageError(true);throw e}};
 async function publishStory(story:Story,clearDraft:boolean){
  const task=writeQueue.current.catch(()=>{}).then(async()=>{assertOwner();
   const next={...mainRef.current,stories:[story,...mainRef.current.stories]};
   await saveStoryState(next,clearDraft);
   mainRef.current=next;setData(next);setStorageError(false);
  });
  writeQueue.current=task;await task;
  setModal(null);setStoryRepost(undefined);setStory(story);toast.success('История сохранена на 24 часа');
 }
 async function saveStoryToCapsule(story:Story){
  const task=writeQueue.current.catch(()=>{}).then(async()=>{assertOwner();
   if(mainRef.current.capsule?.some(entry=>entry.story?.id===story.id))return;
   const next:State={...mainRef.current,capsule:[{id:recordId(),title:'История · '+story.name,text:story.text,collection:'Истории',kind:'note',createdAt:Date.now(),story},...(mainRef.current.capsule||[])]};
   await saveState(next);mainRef.current=next;setData(next);
  });
  writeQueue.current=task;
  try{await task;toast.success('История добавлена в капсулу');}catch{toast.error('Не удалось сохранить историю в капсулу. Проверьте свободную память.');}
 }
 function openProfile(id:string){setProfileTarget(id);if(id!=='me'&&data.spaces.find(s=>s.id===id)?.kind!=='chat'){setSelected(id);setModal('info')}else setModal('profile')}
 function openSpace(id:string){if(id==='saved'){navigate('saved');return}setEditingMessage(null);setReplyTo('');setSelected(id);setMobileChat(true);setMessageSearch('');setShowMessageSearch(false);setData(d=>({...d,spaces:d.spaces.map(s=>s.id===id?{...s,unread:0}:s)}))}
 function setDraft(text:string){setData(d=>({...d,drafts:{...d.drafts,[selected]:text}}))}
 function addMessage(text:string,extra:Partial<Message>={}){const target=selected;if(space.kind==='channel'&&space.signature&&text)text+='\n\n— '+data.profile;setData(d=>({...d,messages:[...d.messages,{id:recordId(),spaceId:target,text,sender:d.profile,own:true,kind:'text',createdAt:Date.now(),...extra}],drafts:{...d.drafts,[target]:''}}))}
 function send(){if(selected.startsWith('!')){if(!draft.trim()||busy)return;if(!network.state.rooms.find(r=>r.id===selected)?.encrypted){toast.error('Отправка в комнату без E2EE запрещена.');return}setBusy(true);void network.engine?.send(selected,draft.trim()).then(()=>setData(d=>({...d,drafts:{...d.drafts,[selected]:''}}))).catch(e=>toast.error(e.message)).finally(()=>setBusy(false));return}if(!ready||voiceDirty||!draft.trim())return;if(editingMessage){setData(d=>({...d,messages:d.messages.map(m=>m.id===editingMessage?{...m,text:draft.trim(),edited:true}:m),drafts:{...d.drafts,[selected]:''}}));setEditingMessage(null)}else{addMessage(draft.trim(),replyTo?{replyTo}:{});setReplyTo('')}}
 function actions(m:Message){if(m.spaceId.startsWith('!'))return null;return <MessageActions message={m} onReply={()=>{setReplyTo(m.text||m.fileName||'Вложение');setEditingMessage(null)}} onEdit={()=>{setEditingMessage(m.id);setReplyTo('');setDraft(m.text)}} onCopy={async()=>{try{await navigator.clipboard.writeText(m.text);toast.success('Текст скопирован')}catch{toast.error('Не удалось скопировать текст')}}} onSave={()=>toggleStar(m.id)} onDelete={()=>{setData(d=>({...d,messages:d.messages.filter(x=>x.id!==m.id)}));toast('Сообщение удалено у вас',{action:{label:'Отменить',onClick:()=>setData(d=>({...d,messages:[...d.messages,m].sort((a,b)=>a.createdAt-b.createdAt)}))}})}}/>}
 async function uploadAvatar(f:File){if(!f.type.startsWith('image/')||f.size>5*1024*1024){toast.error('Выберите изображение до 5 МБ');return}try{const id=recordId();await write('blobs',id,f);setData(d=>({...d,avatarId:id}));toast.success('Фото профиля сохранено')}catch{toast.error('Не удалось сохранить фото')}}

 async function attach(blob:Blob,name:string,kind:Message['kind']='file'){if(selected.startsWith('!')){toast.error('Зашифрованные вложения к локальному транспорту пока не подключены. Файл не отправлен.');throw Error('attachment_unavailable')}if(blob.size>25*1024*1024){toast.error('Максимальный размер вложения — 25 МБ');throw Error('too-large')}setBusy(true);try{const id=recordId();await write('blobs',id,blob);addMessage('',{kind,blobId:id,fileName:name,mime:blob.type});toast.success('Вложение сохранено на устройстве')}catch(e){toast.error('Не удалось сохранить вложение');throw e}finally{setBusy(false)}}
 async function saveVoice(draft:VoiceDraft){if(selected.startsWith('!')){toast.error('Голосовые сообщения к локальному транспорту пока не подключены.');return}
  const target=selected,sourceReply=replyTo;setBusy(true);
  try{
   const voice=await prepareLocalVoice(draft,target,sourceReply);
   const task=writeQueue.current.catch(()=>{}).then(async()=>{assertOwner();
    const next=await saveLocalVoice(mainRef.current,voice);
    mainRef.current=next;setData(next);setStorageError(false);
   });
   writeQueue.current=task;await task;
   if(currentLocalSpace.current===target)setReplyTo('');
  }catch(problem){throw new Error(localVoiceError(problem),{cause:problem})}finally{setBusy(false)}
 }
 async function createSpace(){
  if(!newName.trim()||!ready)return;
  if(!network.engine){toast.error('Сначала подключите Matrix в разделе «Сообщения».');return}
  if(newKind==='channel'){toast.error('Серверные каналы доступны в «Аккаунт и устройства → Группы и каналы». Этот локальный редактор пока не подключён.');return}
  setBusy(true);try{
   const id=newKind==='chat'?await network.engine.sellerRoom(newName.trim(),network.state.session!.baseUrl):await network.engine.createRoom(newName.trim(),groupUsers.split(/[\s,]+/).filter(Boolean));
   setModal(null);setNewName('');setGroupUsers('');await network.open(id);
  }catch(error){toast.error(error instanceof Error?error.message:'Разговор не создан.')}finally{setBusy(false)}
 }
